import { ChevronDown, Plus, Sparkles, PenLine, Flame, X, Loader2, ArrowRight, Waves, Quote, Archive, Star, BookOpen, History, CloudSun, CloudRain, Sun, Zap, Eye, EyeOff, Camera } from 'lucide-react';
import { DAILY_PROMPTS } from '../constants';
import { askBelluhAboutJournal, generateRelationshipForecast, detectPatterns } from '../services/geminiService';
