                                    )}
                                </div>
                            </div>

                            <div className="bg-belluh-50/50 p-5 md:p-6 rounded-2xl border border-belluh-100 flex items-start gap-4 mb-4">
                                <Sparkles size={20} className="text-belluh-400 shrink-0 mt-0.5" />
                                <div>
