                     <button
                        onClick={() => onCompose('DROP_MODE')}
                        className="w-12 h-12 rounded-full bg-slate-900 text-white flex items-center justify-center shadow-lg hover:scale-105 active:scale-95 transition-all ml-1"
                        title="New Drop"
                     >
                        <Camera size={20} />
                     </button>
                </div>
             </div>

             {/* Forecast */}
             {forecast && !isConstellation && !isArchived && showPatterns && (
                 <div className="mb-6 animate-scale-in">
                     <div className="bg-white border border-slate-100 rounded-[1.5rem] p-5 shadow-float flex items-center gap-5 relative overflow-hidden">
                         <div className="absolute top-0 left-0 w-1 h-full bg-[#f0addd]"></div>
                         <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center shrink-0">
                             {isLoadingForecast ? <Loader2 size={20} className="animate-spin text-slate-400" /> : getWeatherIcon(forecast.weather)}
                         </div>
                         <div>
                             <div className="flex items-center gap-2 mb-1">
                                 <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Belluh Forecast</span>
                                 <span className="text-[10px] bg-slate-100 px-1.5 py-0.5 rounded text-slate-600 font-bold">{forecast.velocity} Velocity</span>
                             </div>
                             <p className="text-sm font-serif text-slate-800 leading-snug">{forecast.forecast}</p>
                         </div>
                     </div>
                 </div>
             )}

             {/* Ask Belluh Search */}
             <form 
                onSubmit={handleSearchSubmit} 
                className={`relative bg-white rounded-3xl transition-all duration-300 flex items-center px-4 py-4 ${
                    isSearching || searchAnswer || searchQuery 
                    ? 'shadow-2xl shadow-slate-200/50 ring-1 ring-slate-100 transform -translate-y-1' 
                    : 'shadow-float hover:shadow-lg border border-transparent'
                }`}
             >
                <div className="mr-3">{isSearching ? <Loader2 size={18} className="animate-spin text-belluh-400" /> : <Sparkles size={18} className="text-belluh-300" />}</div>
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder={isArchived ? "Search past memories..." : isConstellation ? "Search across all constellations..." : "Ask Belluh..."} className="flex-1 bg-transparent text-[16px] focus:outline-none font-normal placeholder:text-slate-400" />
                {searchQuery && <button type="button" onClick={() => { setSearchQuery(''); setSearchAnswer(null); }}><X size={16} className="text-slate-400" /></button>}
             </form>

             {/* Search Result Display */}
             {searchAnswer && <div className="mt-4 animate-slide-up bg-white rounded-3xl p-8 shadow-2xl border border-slate-50 relative overflow-hidden"><div className="absolute top-0 left-0 w-1.5 h-full bg-belluh-300"></div><p className="text-slate-800 font-serif leading-loose text-lg">{searchAnswer}</p></div>}
          </div>
       </div>

       <div className="relative min-h-[400px]">
          {/* Timeline Stem */}
          <div className="absolute left-14 md:left-20 top-0 bottom-0 w-px bg-slate-100"></div>

          {/* Daily Ritual - Updated Design */}
          {!hasUserPostedToday && !isArchived && !isConstellation && (
              <div className="relative pl-20 md:pl-24 pr-6 mb-16 animate-slide-up" style={{ animationDelay: '0.1s' }}>
                  <div className="absolute left-14 md:left-20 top-8 w-2 h-2 bg-belluh-300 border-[2px] border-[#fcfcfc] rounded-full z-10 shadow-glow -translate-x-[3.5px]"></div>

                  <button onClick={() => onCompose()} className="w-full text-left group max-w-xl">
                      <div className="bg-white border border-slate-100 shadow-sm hover:shadow-lg rounded-[2rem] p-8 transition-all duration-500 relative overflow-hidden group-hover:border-belluh-100 group-hover:-translate-y-1">
                          <div className="absolute top-0 right-0 p-6 opacity-5 group-hover:opacity-10 transition-opacity"><PenLine size={80} className="rotate-12" /></div>
                          <div className="relative z-10">
                              <div className="flex items-center gap-2 mb-4">
                                  <span className="bg-belluh-50 text-belluh-600 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest">Daily Ritual</span>
                              </div>
                              <h3 className="font-serif text-2xl text-slate-800 leading-tight mb-6 group-hover:text-belluh-600 transition-colors">
                                  {todaysPrompt}
                              </h3>
                              <div className="flex items-center gap-3 text-sm font-bold text-slate-400 group-hover:text-slate-900 transition-colors">
                                  <div className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center border border-slate-100 group-hover:bg-white group-hover:shadow-sm"><Plus size={18} /></div>
                                  <span>Tap to capture</span>
                              </div>
                          </div>
                      </div>
                  </button>
              </div>
          )}

          {/* Timeline Feed */}
          {groupedItems.map((item, index) => {
              // Header with Custom Centered Design
              if ('type' in item && item.type === 'header') {
                  return (
                      <div key={`header-${index}`} className="relative pl-20 md:pl-24 pr-6 mb-8 mt-12 flex items-center opacity-60">
                           <div className="h-px bg-slate-200 flex-1"></div>
                           <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-4">
                               {item.title}
                           </span>
                           <div className="h-px bg-slate-200 flex-1"></div>
                      </div>
                  );
              }

              // Pattern / Spiral Card (The "Kafka" Feature)
              if ('type' in item && item.type === 'pattern') {
                  const pattern = item.data as Insight;
                  const isSpiral = pattern.type === 'Spiral';

                  return (
                    <div key={pattern.id} className="relative pl-20 md:pl-24 pr-6 mb-8 animate-pop">
                        <div className="absolute left-14 md:left-20 top-8 w-2 h-2 bg-white border-[2px] border-slate-200 rounded-full z-10 ring-4 ring-[#fcfcfc] -translate-x-[3.5px]"></div>

                        <div 
                            onClick={() => setSelectedPattern(pattern)}
                            className={`max-w-xl w-full rounded-[2rem] p-8 shadow-xl relative overflow-hidden group cursor-pointer hover:scale-[1.01] transition-transform ${isSpiral ? 'bg-[#CDE9F2] text-cyan-950' : 'bg-white border border-belluh-100'}`}
                        >
                             {/* Abstract Background Art */}
                             {isSpiral && (
                                 <div className="absolute -right-20 -top-20 w-60 h-60 bg-white/40 rounded-full blur-[80px]"></div>
                             )}
                             {!isSpiral && (
                                 <div className="absolute -left-10 -bottom-10 w-40 h-40 bg-belluh-100 rounded-full blur-[60px] opacity-60"></div>
                             )}

                             <div className="relative z-10">
                                <div className="flex items-center gap-2 mb-4">
                                    {isSpiral ? (
                                        <div className="w-8 h-8 rounded-full bg-cyan-900/10 flex items-center justify-center">
                                            <Waves size={16} className="text-cyan-900" />
                                        </div>
                                    ) : (
                                        <div className="w-8 h-8 rounded-full bg-belluh-50 flex items-center justify-center">
                                            <History size={16} className="text-belluh-500" />
                                        </div>
                                    )}
                                    <span className={`text-[10px] font-bold uppercase tracking-widest ${isSpiral ? 'text-cyan-800' : 'text-belluh-500'}`}>
                                        {pattern.title}
                                    </span>
                                </div>

                                <p className={`font-serif text-xl leading-relaxed mb-6 ${isSpiral ? 'text-cyan-950' : 'text-slate-800'}`}>
                                    {pattern.content}
                                </p>

                                <button 
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        setSelectedPattern(pattern);
                                    }}
                                    className={`text-xs font-bold px-5 py-3 rounded-full transition-all flex items-center gap-2 ${isSpiral ? 'bg-white/60 text-cyan-950 hover:bg-white' : 'bg-belluh-50 text-belluh-900 hover:bg-belluh-100'}`}
                                >
                                    {pattern.actionLabel || 'Understand Why'}
                                    <ArrowRight size={14} />
                                </button>
                             </div>
                        </div>
                    </div>
                  )
              }

              // Standard Entry
              const entry = item as JournalEntry;
              const sourceCircle = circles.find(c => c.id === entry.circleId);

              return (
                  <div key={entry.id} className="relative pl-20 md:pl-24 pr-6 group transition-[padding] duration-300" style={{ animationDelay: `${index * 50}ms` }}>
                    <div className="absolute left-14 md:left-20 top-8 w-2 h-2 bg-white border-[2px] border-slate-200 rounded-full z-10 shadow-sm group-hover:border-belluh-300 group-hover:scale-110 transition-all duration-300 ring-4 ring-[#fcfcfc] -translate-x-[3.5px]"></div>
                    <div className="max-w-xl w-full">
                        <EntryCard 
                            entry={entry} 
                            isCurrentUser={entry.userId === currentUserId} 
                            onLike={isArchived ? undefined : onLikeEntry}
                            onAskBelluh={() => handleAskAboutEntry(entry.content)}
                            onDelete={isArchived ? undefined : () => onDeleteEntry(entry.id)}
                            onUpdate={isArchived ? undefined : (content) => onUpdateEntry(entry.id, content)}
                            showContext={isConstellation}
                            circleName={sourceCircle?.name}
                            circleColor={sourceCircle?.themeColor}
                        />
                    </div>
                  </div>
              );
          })}
       </div>
       </div>
    </div>
  );
};

export default Timeline;

import React, { useState, useRef, useEffect } from 'react';
import { EntryType, Mood } from '../types';
import { DAILY_PROMPTS, MOOD_EMOJIS } from '../constants';
import { Mic, Image as ImageIcon, Send, X, Loader2, Music, CheckCircle2, Lock, Globe, Camera } from 'lucide-react';
import { transcribeAudio } from '../services/geminiService';
import { supabase } from '../lib/supabaseClient';

interface JournalProps {
  onAddEntry: (content: string, mood: Mood | undefined, type: EntryType, prompt?: string, isPrivate?: boolean, audioUrl?: string, mediaUrl?: string) => void;
  partnerName: string;
  onTriggerPremium: () => void;
  initialPrompt?: string;
  userName?: string;
  partnerHasEntry?: boolean;
  mode?: 'standard' | 'drop'; // New prop
  onClose?: () => void;
}

const Journal: React.FC<JournalProps> = ({ onAddEntry, partnerName, onTriggerPremium, initialPrompt, mode = 'standard', onClose }) => {
  const [content, setContent] = useState('');
  const [selectedMood, setSelectedMood] = useState<Mood | undefined>(undefined);
  const [dailyPrompt] = useState(initialPrompt || DAILY_PROMPTS[Math.floor(Math.random() * DAILY_PROMPTS.length)]);
  const [isPrivate, setIsPrivate] = useState(false);
  const [step, setStep] = useState<'write' | 'mood' | 'success'>('write');

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [isUploading, setIsUploading] = useState(false); // New state to track upload independently
  const [hasImage, setHasImage] = useState(false);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Drop Mode: Auto-open camera/file dialog on mount if no image
  useEffect(() => {
      if (mode === 'drop' && !hasImage && !imagePreview) {
          // Optional: Auto-trigger camera. Can be annoying if user just wants to see UI first.
          // fileInputRef.current?.click(); 
      }
  }, [mode]);

  const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const text = e.target.value;
      if (mode === 'drop') {
          // Enforce 3 words limit
          const words = text.trim().split(/\s+/).filter(Boolean);
          if (words.length > 3 && (e.nativeEvent as any).inputType !== 'deleteContentBackward') {
              return; // Block input
          }
      }
      setContent(text);
  };

  const handleNext = () => {
      if (mode === 'drop') {
          // For drop, skip mood step, submit directly
          if (!hasImage) return; // Photo required
          handleFinalSubmit();
      } else {
          if(content.trim() || hasImage || audioUrl) setStep('mood');
      }
  }

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus') ? 'audio/webm;codecs=opus' : 'audio/webm';

      const options: MediaRecorderOptions = { mimeType, audioBitsPerSecond: 64000 };
      const mediaRecorder = new MediaRecorder(stream, options);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        if (audioChunksRef.current.length === 0) return;
        const finalMimeType = mediaRecorder.mimeType || mimeType || 'audio/webm';
        const fileExt = finalMimeType.includes('mp4') ? 'mp4' : 'webm';
        const audioBlob = new Blob(audioChunksRef.current, { type: finalMimeType });

        setIsTranscribing(true);
        setIsUploading(true);

        // Upload
        const fileName = `voice-notes/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
        supabase.storage.from('journal-media').upload(fileName, audioBlob, { contentType: finalMimeType })
            .then(({ data, error }) => {
                if (!error && data) {
                    const { data: publicUrlData } = supabase.storage.from('journal-media').getPublicUrl(fileName);
                    setAudioUrl(publicUrlData.publicUrl);
                }
            })
            .finally(() => setIsUploading(false));

        // Transcribe (Optional for Drop, but good for context)
        if (mode !== 'drop') {
            const reader = new FileReader();
            reader.readAsDataURL(audioBlob);
            reader.onloadend = async () => {
                if (reader.result) {
                    const base64Audio = (reader.result as string).split(',')[1];
                    transcribeAudio(base64Audio, finalMimeType)
                        .then(text => setContent(prev => prev + (prev ? ' ' : '') + text))
                        .finally(() => setIsTranscribing(false));
                }
            };
        } else {
            setIsTranscribing(false);
        }
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) { console.error("Mic denied:", err); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const handleMicClick = () => isRecording ? stopRecording() : startRecording();

  const handleImageClick = () => {
      if (hasImage) { setHasImage(false); setImagePreview(null); } 
      else fileInputRef.current?.click();
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => { setImagePreview(reader.result as string); setHasImage(true); };
          reader.readAsDataURL(file);
      }
  };

  const handleFinalSubmit = () => {
       const type = mode === 'drop' ? EntryType.Drop : (hasImage ? EntryType.Photo : (audioUrl ? EntryType.Voice : EntryType.Prompt));
       // Drops are public by default to partner
       const isEntryPrivate = mode === 'drop' ? false : isPrivate; 

       onAddEntry(
           content, 
           selectedMood, 
           type, 
           dailyPrompt, 
           isEntryPrivate, 
           audioUrl || undefined, 
           imagePreview || undefined
       );
       setStep('success');
  };

  const isBusy = isTranscribing || isUploading;

  // --- DROP MODE RENDER ---
  if (mode === 'drop' && step === 'write') {
      return (
          <div className="fixed inset-0 z-[100] bg-[#0f172a] text-white flex flex-col animate-fade-in">
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

              {/* Image Background */}
              {imagePreview ? (
                  <div className="absolute inset-0 z-0">
                      <img src={imagePreview} alt="Drop" className="w-full h-full object-cover opacity-60" />
                      <div className="absolute inset-0 bg-gradient-to-t from-[#0f172a] via-transparent to-[#0f172a]/60"></div>
                  </div>
              ) : (
                  <div className="absolute inset-0 z-0 flex flex-col items-center justify-center cursor-pointer" onClick={handleImageClick}>
                      {/* Interactive area maintained but visual is handled in main column */}
                  </div>
              )}

              {/* Top Bar */}
              <div className="relative z-10 flex justify-between items-center p-6 pt-8 md:p-10">
                  <button 
                    onClick={onClose} 
                    className="w-12 h-12 flex items-center justify-center bg-white/10 backdrop-blur-xl rounded-full text-white hover:bg-white/20 transition-all border border-white/5"
                  >
                      <X size={24} />
                  </button>
                  <span className="text-xs font-bold uppercase tracking-[0.25em] text-white/80 drop-shadow-md">New Drop</span>
                  <div className="w-12"></div>
              </div>

              {/* Main Content Area */}
              <div className="flex-1 relative z-10 flex flex-col justify-center items-center p-6 w-full max-w-3xl mx-auto space-y-10">
                  <textarea
                      value={content}
                      onChange={handleContentChange}
                      placeholder="3 words..."
                      className="w-full bg-transparent text-center text-6xl md:text-7xl lg:text-8xl font-serif font-bold text-white placeholder:text-white/20 focus:outline-none resize-none drop-shadow-2xl leading-tight"
                      rows={2}
                      maxLength={30}
                      autoFocus
                  />

                  {!imagePreview && (
                      <button 
                        onClick={handleImageClick}
                        className="flex flex-col items-center gap-3 group animate-float"
                      >
                          <div className="w-20 h-16 rounded-[1.5rem] border-2 border-dashed border-white/30 flex items-center justify-center group-hover:border-white group-hover:bg-white/5 transition-all">
                              <Camera size={32} className="text-white/60 group-hover:text-white transition-colors" />
                          </div>
                          <span className="text-[10px] font-bold uppercase tracking-widest text-white/50 group-hover:text-white transition-colors">Tap to Capture</span>
                      </button>
                  )}

                  {/* Audio Waveform */}
                  {audioUrl && (
                      <div className="flex items-center gap-3 bg-white/10 backdrop-blur-xl px-5 py-3 rounded-full border border-white/10 animate-slide-up">
                          <Music size={16} className="text-[#f0addd]" />
                          <div className="flex gap-1 h-4 items-center">
                              {[1,2,3,2,1,2,3,4,3,2,1,2,3,2,1].map((h,i) => (
                                  <div key={i} className="w-1 bg-white/90 rounded-full animate-pulse" style={{height: `${h*4}px`, animationDelay: `${i*0.05}s`}}></div>
                              ))}
                          </div>
                      </div>
                  )}
              </div>

              {/* Bottom Actions */}
              <div className="relative z-10 p-8 pb-12 md:pb-16 flex items-center justify-between w-full max-w-4xl mx-auto">
                  <button 
                    onClick={handleMicClick} 
                    className={`w-16 h-16 rounded-full flex items-center justify-center transition-all ${isRecording ? 'bg-red-500 scale-110 shadow-[0_0_30px_rgba(239,68,68,0.4)]' : 'bg-white/10 backdrop-blur-xl border border-white/10 hover:bg-white/20'}`}
                  >
                      {isRecording ? <div className="w-6 h-6 bg-white rounded-sm animate-pulse" /> : <Mic size={24} className="text-white" />}
                  </button>

                  {imagePreview && (
                      <button onClick={handleImageClick} className="text-[10px] font-bold uppercase tracking-widest text-white/50 hover:text-white transition-colors bg-black/40 px-4 py-2 rounded-full backdrop-blur-sm">
                          Retake Photo
                      </button>
                  )}

                  <button 
                    onClick={handleNext}
                    disabled={!hasImage || !content.trim() || isBusy} 
                    className="h-16 px-10 bg-white text-black rounded-full font-bold text-lg flex items-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_40px_-5px_rgba(255,255,255,0.3)] hover:scale-105 active:scale-95 transition-all"
                  >
                      <span>Drop It</span> <Send size={20} />
                  </button>
              </div>
          </div>
      );
  }

  // --- STANDARD MODE RENDER (Existing) ---
  return (
    <div className="pb-32 pt-16 px-6 max-w-xl mx-auto h-full flex flex-col relative overflow-hidden">
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />
      <div className="fixed top-[-20%] right-[-10%] w-[600px] h-[600px] bg-belluh-300/10 rounded-full blur-[100px] pointer-events-none"></div>

      {step === 'success' ? (
        <div className="flex-1 flex flex-col items-center justify-center animate-scale-in">
           <div className="relative mb-8">
              <div className="w-24 h-24 bg-belluh-50 rounded-full flex items-center justify-center animate-pulse-slow">
                 <CheckCircle2 size={40} className="text-belluh-400" />
              </div>
           </div>
           <h2 className="text-3xl font-serif text-slate-900 mb-3 text-center">{mode === 'drop' ? 'Dropped!' : 'Moment Captured'}</h2>
           <p className="text-slate-500 text-sm font-medium tracking-wide text-center max-w-xs leading-relaxed">
               {mode === 'drop' ? `${partnerName} has been notified.` : (!isPrivate ? `Belluh will remind ${partnerName} tonight.` : "Saved to your private vault.")}
           </p>
           {mode === 'drop' && onClose && (
               <button onClick={onClose} className="mt-8 px-8 py-3 bg-slate-900 text-white rounded-full font-bold text-sm">Close</button>
           )}
        </div>
      ) : (
        <div className="relative flex-1 flex flex-col">
            <div className={`transition-all duration-500 flex-1 flex flex-col ${step === 'write' ? 'opacity-100 scale-100 z-10' : 'opacity-0 scale-95 pointer-events-none absolute inset-0'}`}>
                <div className="mb-8 mt-4">
                    <p className="text-xs font-bold text-belluh-400 uppercase tracking-widest mb-3">Daily Ritual</p>
                    <p className="text-2xl text-slate-800 font-serif leading-tight">{dailyPrompt}</p>
                </div>
                <div className="space-y-4 mb-4">
                    {hasImage && imagePreview && (
                        <div className="relative w-full h-48 rounded-2xl overflow-hidden shadow-sm animate-scale-in group">
                            <img src={imagePreview} alt="Attached" className="w-full h-full object-cover" />
                            <button onClick={handleImageClick} className="absolute top-2 right-2 bg-black/50 text-white p-1.5 rounded-full backdrop-blur-md">
                                <X size={14} />
                            </button>
                        </div>
                    )}
                    {(audioUrl || isUploading) && !isRecording && (
                        <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl border border-slate-100 animate-slide-up">
                            <div className="w-10 h-10 bg-slate-900 rounded-full flex items-center justify-center text-white">
                                {isUploading ? <Loader2 size={16} className="animate-spin" /> : <Mic size={16} />}
                            </div>
                            <div className="flex-1 text-xs font-bold">
                                {isUploading ? "Syncing Audio..." : "Voice Note Ready"}
                            </div>
                        </div>
                    )}
                </div>
                <textarea
                    value={content}
                    onChange={(e) => setContent(e.target.value)}
                    placeholder={isTranscribing ? "Transcribing your thoughts..." : "Start typing..."}
                    className="w-full bg-transparent text-slate-800 placeholder:text-slate-300 focus:outline-none resize-none font-serif text-xl leading-relaxed flex-1 transition-opacity duration-300"
                    style={{ opacity: isTranscribing ? 0.5 : 1 }}
                    autoFocus
                    disabled={isTranscribing}
                />
                <div className="mt-auto pt-6 flex items-center justify-between">
                    <div className="flex gap-2">
                         <button onClick={handleMicClick} disabled={isBusy} className={`h-12 px-5 rounded-full flex items-center gap-2 transition-all ${isRecording ? 'bg-red-50 text-red-500' : 'bg-slate-50 text-slate-500'}`}>
                            {isRecording ? <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" /> : (isTranscribing ? <Loader2 size={18} className="animate-spin" /> : <Mic size={18} />)}
                        </button>
                        {!isRecording && !isBusy && <button onClick={handleImageClick} className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${hasImage ? 'bg-belluh-50 text-belluh-600' : 'bg-slate-50 text-slate-500'}`}><ImageIcon size={18} /></button>}
                    </div>
                    {(content.trim() || hasImage || audioUrl) && !isRecording && !isBusy && (
                        <button onClick={handleNext} className="h-12 px-8 bg-slate-900 text-white rounded-full font-bold text-sm flex items-center gap-2">
                            <span>Next</span> <Send size={14} />
                        </button>
                    )}
                </div>
            </div>
            <div className={`transition-all duration-500 flex flex-col h-full ${step === 'mood' ? 'opacity-100 scale-100 z-10' : 'opacity-0 translate-x-10 pointer-events-none absolute inset-0'}`}>
                 <div className="flex justify-between items-center mb-10">
                    <h3 className="text-slate-800 font-serif text-2xl">How did this feel?</h3>
                    <button onClick={() => setStep('write')} className="text-xs font-bold text-slate-400 uppercase tracking-widest">Back</button>
                 </div>
                 <div className="grid grid-cols-4 gap-4 mb-auto">
                    {Object.values(Mood).map((m) => (
                        <button key={m} onClick={() => setSelectedMood(m)} className={`aspect-square rounded-2xl flex flex-col items-center justify-center transition-all ${selectedMood === m ? 'bg-white shadow-apple ring-2 ring-belluh-300' : 'bg-slate-50/50'}`}>
                        <span className="text-3xl">{MOOD_EMOJIS[m]}</span>
                        </button>
                    ))}
                 </div>
                 <div className="space-y-4 mb-8">
                     <div className="bg-slate-50 p-1.5 rounded-xl flex">
                         <button onClick={() => setIsPrivate(false)} className={`flex-1 py-3 rounded-lg text-xs font-bold uppercase transition-all ${!isPrivate ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}><Globe size={14} className="inline mr-2" />Share</button>
                         <button onClick={() => setIsPrivate(true)} className={`flex-1 py-3 rounded-lg text-xs font-bold uppercase transition-all ${isPrivate ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}><Lock size={14} className="inline mr-2" />Private</button>
                     </div>
                 </div>
                 <button onClick={handleFinalSubmit} disabled={!selectedMood} className={`w-full py-4 rounded-full font-bold text-sm shadow-xl flex items-center justify-center gap-2 ${selectedMood ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-300'}`}>
                    <span>Save to Story</span> <Send size={16} />
                 </button>
            </div>
        </div>
      )}
    </div>
  );
};

export default Journal;

import React, { useState, useMemo, useEffect } from 'react';
import TabBar from './components/TabBar';
import Journal from './pages/Journal';
import Timeline from './pages/Timeline';
import AICoach from './pages/AICoach';
import Profile from './pages/Profile';
import Onboarding from './pages/Onboarding';
import Auth from './pages/Auth';
import LandingPage from './pages/LandingPage';
import About from './pages/About';
import AdminMetrics from './pages/AdminMetrics';
import LegalModal from './components/LegalModal';
import ArtifactModal from './components/ArtifactModal';
import { CURRENT_USER, MOCK_INSIGHTS, THEMES } from './constants';
import { JournalEntry, EntryType, Mood, User, CircleType, CircleStatus, ColorTheme } from './types';
import { Sparkles, X, CheckCircle2, AlertCircle, Info } from 'lucide-react';
import { supabase } from './lib/supabaseClient';
import { useAdminAccess } from './hooks/useAdminAccess';
import { trackEvent } from './services/analytics';
import { fetchInitialData, getSignedStorageUrl } from './services/dataLoader';

// Toast Component
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgColors = {
    success: 'bg-slate-900 text-white',
    error: 'bg-rose-500 text-white',
    info: 'bg-belluh-300 text-slate-900',
  };

  const Icons = {
    success: CheckCircle2,
    error: AlertCircle,
    info: Info,
  };

  const Icon = Icons[type];

  return (
    <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[200] flex items-center gap-3 px-6 py-4 rounded-full shadow-2xl animate-slide-up ${bgColors[type]}`}>
      <Icon size={18} strokeWidth={2.5} />
      <span className="text-sm font-bold">{message}</span>
    </div>
  );
};

// Types for Invite Handling
type PendingInvite = {
  id: string; // Connection ID
  inviter: {
    id: string;
    name: string;
    avatar: string;
  }
};

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isOnboarding, setIsOnboarding] = useState(false);

  // View State
  const [authView, setAuthView] = useState<'landing' | 'auth' | 'about'>('landing');
  const [authMode, setAuthMode] = useState<'login' | 'signup'>('signup');

  // App State
  const [currentTab, setCurrentTab] = useState('timeline');
  const [isComposeOpen, setIsComposeOpen] = useState(false);
  const [composePrompt, setComposePrompt] = useState<string | undefined>(undefined);
  const [entries, setEntries] = useState<JournalEntry[]>([]);
  const [streak, setStreak] = useState(0);

  // Pending Invites State
  const [pendingInvites, setPendingInvites] = useState<PendingInvite[]>([]);

  // Notification State
  const [notification, setNotification] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);

  const showNotification = (message: string, type: 'success' | 'error' | 'info' = 'success') => {
    setNotification({ message, type });
  };

  // Initialize with empty user state
  const [user, setUser] = useState<User>({
      id: '',
      name: '',
      avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=guest',
      partnerName: undefined,
      circles: [],
      isPremium: false,
      joinDate: new Date(),
      activeCircleId: 'c1',
      settings: CURRENT_USER.settings,
      hasCompletedOnboarding: false,
      detectedPersona: CURRENT_USER.detectedPersona
  });

  const [showPremiumOverlay, setShowPremiumOverlay] = useState(false);
  const [legalModalOpen, setLegalModalOpen] = useState<'tos' | 'privacy' | null>(null);
  const [artifactModalOpen, setArtifactModalOpen] = useState<'reel' | 'letter' | null>(null);

  // STEALTH ADMIN ACCESS HOOK
  const { showAdmin, setShowAdmin, isUserAdmin } = useAdminAccess(user.id);

  // Apply Theme
  useEffect(() => {
    const root = document.documentElement;
    const theme = THEMES[user.settings.colorTheme] || THEMES.pink;
    Object.entries(theme).forEach(([key, value]) => {
      root.style.setProperty(`--color-belluh-${key}`, value as string);
    });
    // Helper for RGB shadow glow
    const hex = theme[300] as string; 
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    root.style.setProperty('--color-belluh-300-rgb', `${r}, ${g}, ${b}`);
  }, [user.settings.colorTheme]);

  // ... (Auth Helpers loadUserData, resetUserState - unchanged) ...
  const resetUserState = () => {
      setIsAuthenticated(false);
      setEntries([]);
      setStreak(0);
      setUser({
          id: '',
          name: '',
          avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=guest',
          partnerName: undefined,
          circles: [],
          isPremium: false,
          joinDate: new Date(),
          activeCircleId: 'c1',
          settings: CURRENT_USER.settings,
          hasCompletedOnboarding: false,
          detectedPersona: CURRENT_USER.detectedPersona
      });
      setIsLoading(false);
  };

  const loadUserData = async (sessionUser: any) => {
      try {
        trackEvent('app_opened', { source: 'web' });

        // Handle Invites (Persistent)
        const params = new URLSearchParams(window.location.search);
        let inviteId = params.get('invite');
        if (!inviteId) inviteId = localStorage.getItem('pending_invite_id');

        if (inviteId && inviteId !== sessionUser.id) {
            const { data: existing } = await supabase
                .from('partner_connections')
                .select('*')
                .or(`and(user_id.eq.${inviteId},partner_id.eq.${sessionUser.id}),and(user_id.eq.${sessionUser.id},partner_id.eq.${inviteId})`);

            if (!existing || existing.length === 0) {
                await supabase.from('partner_connections').insert({
                    user_id: inviteId,
                    partner_id: sessionUser.id,
                    status: 'pending'
                });
                showNotification("Invite received! Check your profile.", "success");
            }
            localStorage.removeItem('pending_invite_id');
        }

        try {
            const url = new URL(window.location.href);
            if (url.searchParams.has('invite')) {
                url.searchParams.delete('invite');
                window.history.replaceState({}, document.title, url.toString());
            }
        } catch (e) { console.debug(e); }

        // Core Data Load via Service
        const data = await fetchInitialData(sessionUser);

        setUser(data.user);
        setEntries(data.entries);
        setStreak(data.streak);
        setPendingInvites(data.pendingInvites);
        setIsOnboarding(data.isOnboarding);
        setIsAuthenticated(true);

      } catch (err) {
          console.error("Failed to load user data", err);
      } finally {
          setIsLoading(false);
      }
  };

  useEffect(() => {
    let mounted = true;
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
        if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED') {
            if (session?.user && mounted) {
                loadUserData(session.user);
            }
        } else if (event === 'SIGNED_OUT') {
            if (mounted) resetUserState();
        }
    });

    supabase.auth.getSession().then(({ data: { session } }) => {
        if (session?.user && mounted) loadUserData(session.user);
        else if (mounted) setIsLoading(false);
    });

    return () => { 
        mounted = false;
        subscription.unsubscribe();
    };
  }, []);

  const partnerHasEntry = useMemo(() => {
    const today = new Date();
    return entries.some(e => 
        e.userId !== user.id && 
        e.circleId === user.activeCircleId &&
        e.timestamp.getDate() === today.getDate() && 
        e.timestamp.getMonth() === today.getMonth() &&
        e.timestamp.getFullYear() === today.getFullYear()
    );
  }, [entries, user.id, user.activeCircleId]);

  const handleTriggerPremium = () => {
    trackEvent('premium_trigger_clicked');
    setShowPremiumOverlay(true);
  };

  const handleLogin = () => {};

  const handleLogout = async () => {
      try {
        await supabase.auth.signOut();
      } finally {
        resetUserState();
      }
  };

  const handleOnboardingComplete = async (partnerName: string, firstEntry: string) => {
    const { data: { user: currentUser } } = await supabase.auth.getUser();
    if (!currentUser) return;

    await supabase.from('profiles').update({ partner_name: partnerName }).eq('id', currentUser.id);
    await supabase.from('journal_entries').insert([{
        user_id: currentUser.id,
        content: firstEntry,
        type: 'Freeform', 
        is_shared: false, 
        is_favorite: false,
        tags: ['onboarding', 'first_magic_moment', 'circle:c1'], 
        date: new Date().toISOString()
    }]);

    setUser(prev => ({ ...prev, partnerName, hasCompletedOnboarding: true }));
    setIsOnboarding(false);
    loadUserData(currentUser);
  };

  const handleUpdateUser = async (updates: Partial<User>) => {
      if (updates.relationshipFacts) {
          setUser(prev => ({ ...prev, ...updates }));
          return;
      }

      // Theme Update
      if (updates.settings) {
          setUser(prev => ({ ...prev, settings: { ...prev.settings, ...updates.settings } }));
          // Ideally save to DB here
          return;
      }

      const { data: { user: currentUser } } = await supabase.auth.getUser();
      if (!currentUser) return;

      const updatePayload: any = {
          id: currentUser.id,
          email: currentUser.email,
          full_name: updates.name !== undefined ? updates.name : user.name,
          avatar_url: updates.avatar !== undefined ? updates.avatar : user.avatar
      };

      await supabase.from('profiles').upsert(updatePayload);
      setUser(prev => ({ ...prev, name: updatePayload.full_name, avatar: updatePayload.avatar_url }));
      showNotification('Profile updated', 'success');
  };

  const handleCreateCircle = async (name: string) => {
      const { data: { user: currentUser } } = await supabase.auth.getUser();
      if (!currentUser) return;

      const randomColor = '#' + Math.floor(Math.random()*16777215).toString(16).padStart(6, '0');
      const { error } = await supabase.from('journal_entries').insert([{
          user_id: currentUser.id,
          title: name,
          content: randomColor, 
          type: 'Milestone', 
          tags: ['system_circle_def'], 
          is_shared: false,
          date: new Date().toISOString()
      }]);

      if (!error) {
          showNotification('New circle created!', 'success');
          loadUserData(currentUser);
      } else {
          showNotification('Failed to create circle.', 'error');
      }
  };

  const handleRenameCircle = async (circleId: string, newName: string) => {
      const { data: { user: currentUser } } = await supabase.auth.getUser();
      if (!currentUser) return;

      const isCustom = user.circles.find(c => c.id === circleId && c.type === CircleType.Custom && !c.id.startsWith('c1') && !c.id.startsWith('partner_'));

      if (isCustom) {
          const { error } = await supabase.from('journal_entries').update({ title: newName }).eq('id', circleId);
          if (!error) {
              setUser(prev => ({
                  ...prev,
                  circles: prev.circles.map(c => c.id === circleId ? { ...c, name: newName } : c)
              }));
              showNotification('Circle renamed', 'success');
          }
      } else {
          const { data: existingMeta } = await supabase
            .from('journal_entries')
            .select('id, tags')
            .contains('tags', ['system_circle_metadata', `circle:${circleId}`])
            .maybeSingle();

          if (existingMeta) {
              await supabase.from('journal_entries').update({ title: newName }).eq('id', existingMeta.id);
          } else {
              await supabase.from('journal_entries').insert([{
                  user_id: currentUser.id,
                  title: newName,
                  type: 'Milestone',
                  tags: ['system_circle_metadata', `circle:${circleId}`],
                  is_shared: true,
                  date: new Date().toISOString()
              }]);
          }

          setUser(prev => ({
              ...prev,
              circles: prev.circles.map(c => c.id === circleId ? { ...c, name: newName } : c)
          }));
          showNotification('Circle renamed', 'success');
      }
  };

  const handleArchiveCircle = async (circleId: string) => {
      const { data: { user: currentUser } } = await supabase.auth.getUser();
      if (!currentUser) return;

      const circle = user.circles.find(c => c.id === circleId);
      if (!circle) return;

      const isArchiving = circle.status === CircleStatus.Active;
      const newStatus = isArchiving ? CircleStatus.Archived : CircleStatus.Active;

      const isCustom = circle.type === CircleType.Custom && !circle.id.startsWith('c1') && !circle.id.startsWith('partner_');

      if (isCustom) {
          const { data: entry } = await supabase.from('journal_entries').select('tags').eq('id', circleId).single();
          if (entry) {
              let newTags = entry.tags || [];
              if (isArchiving) newTags.push('status:archived');
              else newTags = newTags.filter((t: string) => t !== 'status:archived');
              await supabase.from('journal_entries').update({ tags: newTags }).eq('id', circleId);
          }
      } else {
          const { data: existingMeta } = await supabase
            .from('journal_entries')
            .select('id, tags')
            .contains('tags', ['system_circle_metadata', `circle:${circleId}`])
            .maybeSingle();

          if (existingMeta) {
              let newTags = existingMeta.tags || [];
              if (isArchiving) newTags.push('status:archived');
              else newTags = newTags.filter((t: string) => t !== 'status:archived');
              await supabase.from('journal_entries').update({ tags: newTags }).eq('id', existingMeta.id);
          } else {
              await supabase.from('journal_entries').insert([{
                  user_id: currentUser.id,
                  type: 'Milestone',
                  tags: ['system_circle_metadata', `circle:${circleId}`, isArchiving ? 'status:archived' : ''],
                  is_shared: true,
                  date: new Date().toISOString()
              }]);
          }
      }

      setUser(prev => ({
          ...prev,
          circles: prev.circles.map(c => c.id === circleId ? { ...c, status: newStatus } : c)
      }));
      showNotification(isArchiving ? 'Circle archived' : 'Circle restored', 'success');
  };

  const handleAcceptInvite = async (connectionId: string) => {
      setPendingInvites(prev => prev.filter(i => i.id !== connectionId));
      try {
          const { error } = await supabase
              .from('partner_connections')
              .update({ status: 'connected' })
              .eq('id', connectionId);
          if (error) throw error;
          showNotification('Invite accepted!', 'success');
          const { data: { user } } = await supabase.auth.getUser();
          if (user) loadUserData(user);
      } catch (error) {
          showNotification('Failed to accept', 'error');
          const { data: { user } } = await supabase.auth.getUser();
          if (user) loadUserData(user);
      }
  };

  const handleDeclineInvite = async (connectionId: string) => {
      setPendingInvites(prev => prev.filter(i => i.id !== connectionId));
      try {
          await supabase.from('partner_connections').delete().eq('id', connectionId);
          showNotification('Invite declined', 'success');
      } catch (error) {
          showNotification('Failed to decline', 'error');
      }
  };

  const handleCompose = (prompt?: string) => {
      setComposePrompt(prompt);
      setIsComposeOpen(true);
  };

  const handleAddEntry = async (content: string, mood: Mood | undefined, type: EntryType, prompt?: string, isPrivate?: boolean, audioUrl?: string, mediaUrl?: string) => {
    const { data: { user: currentUser } } = await supabase.auth.getUser();
    if (!currentUser) return;

    let signedAudioUrl = audioUrl;
    let signedPhotoUrl = mediaUrl;

    if (audioUrl && !audioUrl.includes('?token=')) {
        const fileName = audioUrl.split('/').pop();
        if (fileName) signedAudioUrl = await getSignedStorageUrl('journal-media', fileName, 3600);
    }
    if (mediaUrl && !mediaUrl.includes('?token=') && !mediaUrl.startsWith('data:')) {
        const fileName = mediaUrl.split('/').pop();
        if (fileName) signedPhotoUrl = await getSignedStorageUrl('journal-media', fileName, 3600);
    }

    // Drops are pending nomination by default if 'Drop' type
    const tags = [`circle:${user.activeCircleId}`];
    if (type === EntryType.Drop) tags.push('status:pending_nomination');

    const { data, error } = await supabase.from('journal_entries').insert([{
        user_id: currentUser.id,
        content,
        type,
        mood,
        title: prompt,
        is_shared: !isPrivate,
        audio_url: signedAudioUrl,
        photo_url: signedPhotoUrl,
        date: new Date().toISOString(),
        tags
    }]).select().single();

    if (data && !error) {
         trackEvent('journal_entry_created', { type, mood });
         const newEntry: JournalEntry = {
            id: data.id,
            userId: currentUser.id,
            authorName: user.name,
            authorAvatar: user.avatar,
            content,
            timestamp: new Date(data.created_at),
            type,
            mood,
            prompt,
            isPrivate: isPrivate || false,
            circleId: user.activeCircleId, 
            likes: 0,
            isLiked: false,
            audioUrl: signedAudioUrl || undefined,
            mediaUrl: signedPhotoUrl || undefined,
            nominationStatus: type === EntryType.Drop ? 'pending' : undefined
        };
        setEntries(prev => [newEntry, ...prev]);
        setIsComposeOpen(false); 
        setComposePrompt(undefined);
        showNotification(type === EntryType.Drop ? 'Drop sent!' : 'Memory captured!', 'success');
    } else {
        showNotification('Failed to save.', 'error');
    }
  };

  const handleUpdateEntry = async (entryId: string, newContent: string) => {
    const { error } = await supabase.from('journal_entries').update({ content: newContent }).eq('id', entryId);
    if (!error) {
        setEntries(prev => prev.map(e => e.id === entryId ? { ...e, content: newContent } : e));
        showNotification('Entry updated', 'success');
    }
  };

  const handleDeleteEntry = async (entryId: string) => {
      const { error } = await supabase.from('journal_entries').delete().eq('id', entryId);
      if (!error) {
        setEntries(prev => prev.filter(e => e.id !== entryId));
        showNotification('Entry deleted', 'success');
      }
  };

  const handleLikeEntry = async (entryId: string) => {
    const entry = entries.find(e => e.id === entryId);
    if (!entry) return;
    const newLikedState = !entry.isLiked;

    setEntries(prevEntries => prevEntries.map(e => {
      if (e.id === entryId) {
        return { ...e, isLiked: newLikedState, likes: (e.likes || 0) + (newLikedState ? 1 : -1) };
      }
      return e;
    }));

    await supabase.from('journal_entries').update({ is_favorite: newLikedState }).eq('id', entryId);
  };

  const handleCircleChange = (circleId: string) => setUser({...user, activeCircleId: circleId});

  // --- Rendering ---
  if (isLoading) return <div className="min-h-screen bg-[#fcfcfc] flex items-center justify-center"><Sparkles className="text-belluh-300 w-10 h-10 mb-4 animate-pulse" /></div>;
  if (showAdmin && isUserAdmin) return <AdminMetrics onBack={() => setShowAdmin(false)} />;

  // ... (Auth checks, Onboarding, same as before) ...
  if (!isAuthenticated) {
      if (authView === 'landing') {
          return (
              <>
                <LandingPage 
                    onGetStarted={() => { setAuthMode('signup'); setAuthView('auth'); }} 
                    onLogin={() => { setAuthMode('login'); setAuthView('auth'); }} 
                    onShowLegal={(type) => setLegalModalOpen(type)} 
                    onGoToAbout={() => setAuthView('about')} 
                />
                {legalModalOpen && <LegalModal type={legalModalOpen} onClose={() => setLegalModalOpen(null)} />}
                {notification && <Toast message={notification.message} type={notification.type} onClose={() => setNotification(null)} />}
              </>
          );
      }
      if (authView === 'about') return <About onBack={() => setAuthView('landing')} onGetStarted={() => { setAuthMode('signup'); setAuthView('auth'); }} onLogin={() => { setAuthMode('login'); setAuthView('auth'); }} />;
      return <><Auth initialView={authMode} onLogin={handleLogin} onShowLegal={(type) => setLegalModalOpen(type)} onShowToast={showNotification} />{legalModalOpen && <LegalModal type={legalModalOpen} onClose={() => setLegalModalOpen(null)} />}{notification && <Toast message={notification.message} type={notification.type} onClose={() => setNotification(null)} />}</>;
  }

  if (isOnboarding) return <Onboarding onComplete={handleOnboardingComplete} />;

  return (
    <div className="bg-paper min-h-screen text-slate-800 font-sans selection:bg-belluh-100 selection:text-belluh-900 overflow-x-hidden animate-fade-in">
      {currentTab === 'timeline' && <Timeline entries={entries.filter(e => user.activeCircleId === 'constellation' || e.circleId === user.activeCircleId)} currentUserId={user.id} onTriggerPremium={handleTriggerPremium} activeCircleId={user.activeCircleId} circles={user.circles} onCircleChange={handleCircleChange} onLikeEntry={handleLikeEntry} onCompose={handleCompose} onDeleteEntry={handleDeleteEntry} onUpdateEntry={handleUpdateEntry} streak={streak} />}
      {currentTab === 'ai-coach' && <AICoach insights={MOCK_INSIGHTS} entryTexts={entries.map(e => e.content)} onTriggerPremium={handleTriggerPremium} />}
      {currentTab === 'profile' && <Profile user={user} entries={entries} streak={streak} onCircleChange={handleCircleChange} onCreateCircle={handleCreateCircle} onArchiveCircle={handleArchiveCircle} onRenameCircle={handleRenameCircle} onLogout={handleLogout} onUpdateUser={handleUpdateUser} onShowLegal={(type) => setLegalModalOpen(type)} onViewArtifact={(type) => setArtifactModalOpen(type)} onShowToast={showNotification} pendingInvites={pendingInvites} onAcceptInvite={handleAcceptInvite} onDeclineInvite={handleDeclineInvite} />}

      {notification && <Toast message={notification.message} type={notification.type} onClose={() => setNotification(null)} />}
      <TabBar currentTab={currentTab} onTabChange={(tab) => { trackEvent('tab_changed', { tab }); setCurrentTab(tab); }} onCompose={() => handleCompose()} />
      {isComposeOpen && <div className="fixed inset-0 z-[60] bg-paper animate-slide-up"><button onClick={() => setIsComposeOpen(false)} className={`absolute top-6 right-6 w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-500 hover:bg-slate-200 z-50 transition-colors ${composePrompt === 'DROP_MODE' ? 'hidden' : ''}`}><X size={20} /></button><Journal onAddEntry={handleAddEntry} partnerName={user.partnerName || 'Partner'} onTriggerPremium={handleTriggerPremium} initialPrompt={composePrompt === 'DROP_MODE' ? 'New Drop' : composePrompt} userName={user.name} partnerHasEntry={partnerHasEntry} mode={composePrompt === 'DROP_MODE' ? 'drop' : 'standard'} onClose={() => setIsComposeOpen(false)} /></div>}

      {legalModalOpen && <LegalModal type={legalModalOpen} onClose={() => setLegalModalOpen(null)} />}

      {artifactModalOpen && <ArtifactModal type={artifactModalOpen} onClose={() => setArtifactModalOpen(null)} entries={entries} currentUserId={user.id} userName={user.name} partnerName={user.partnerName || 'Partner'} />}
      {showPremiumOverlay && <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowPremiumOverlay(false)}><div className="bg-white rounded-[2.5rem] p-10 max-w-sm w-full text-center relative overflow-hidden shadow-2xl animate-scale-in" onClick={e => e.stopPropagation()}><div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-belluh-300 via-purple-300 to-indigo-300" /><div className="w-20 h-20 bg-belluh-50 rounded-full flex items-center justify-center mx-auto mb-6 shadow-apple animate-float"><Sparkles size={32} className="text-belluh-500" /></div><h2 className="text-3xl font-serif text-slate-900 mb-3 tracking-tight">Belluh Premium</h2><p className="text-slate-500 mb-8 text-sm leading-relaxed font-medium">Unlock deeper intimacy.</p><button onClick={() => setShowPremiumOverlay(false)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm hover:bg-black transition-transform active:scale-95 shadow-xl shadow-slate-200">Start Free Trial</button><button onClick={() => setShowPremiumOverlay(false)} className="w-full py-3 text-xs text-slate-400 hover:text-slate-600 font-bold uppercase tracking-widest">Maybe Later</button></div></div>}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { EntryType, Mood } from '../types';
import { DAILY_PROMPTS, MOOD_EMOJIS } from '../constants';
import { Mic, Image as ImageIcon, Send, X, Loader2, Music, CheckCircle2, Lock, Globe, Camera, RefreshCw } from 'lucide-react';
import { transcribeAudio } from '../services/geminiService';
import { supabase } from '../lib/supabaseClient';

interface JournalProps {
  onAddEntry: (content: string, mood: Mood | undefined, type: EntryType, prompt?: string, isPrivate?: boolean, audioUrl?: string, mediaUrl?: string) => void;
  partnerName: string;
  onTriggerPremium: () => void;
  initialPrompt?: string;
  userName?: string;
  partnerHasEntry?: boolean;
  mode?: 'standard' | 'drop'; // New prop
  onClose?: () => void;
}

const Journal: React.FC<JournalProps> = ({ onAddEntry, partnerName, onTriggerPremium, initialPrompt, mode = 'standard', onClose }) => {
  const [content, setContent] = useState('');
  const [selectedMood, setSelectedMood] = useState<Mood | undefined>(undefined);
  const [dailyPrompt] = useState(initialPrompt || DAILY_PROMPTS[Math.floor(Math.random() * DAILY_PROMPTS.length)]);
  const [isPrivate, setIsPrivate] = useState(false);
  const [step, setStep] = useState<'write' | 'mood' | 'success'>('write');

  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [isUploading, setIsUploading] = useState(false); // New state to track upload independently
  const [hasImage, setHasImage] = useState(false);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Drop Mode: Auto-open camera/file dialog on mount if no image
  useEffect(() => {
      if (mode === 'drop' && !hasImage && !imagePreview) {
          // Optional: Auto-trigger camera. Can be annoying if user just wants to see UI first.
          // fileInputRef.current?.click(); 
      }
  }, [mode]);

  const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const text = e.target.value;
      if (mode === 'drop') {
          // Enforce 3 words limit
          const words = text.trim().split(/\s+/).filter(Boolean);
          if (words.length > 3 && (e.nativeEvent as any).inputType !== 'deleteContentBackward') {
              return; // Block input
          }
      }
      setContent(text);
  };

  const handleNext = () => {
      if (mode === 'drop') {
          // For drop, skip mood step, submit directly
          if (!hasImage) return; // Photo required
          handleFinalSubmit();
      } else {
          if(content.trim() || hasImage || audioUrl) setStep('mood');
      }
  }

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus') ? 'audio/webm;codecs=opus' : 'audio/webm';

      const options: MediaRecorderOptions = { mimeType, audioBitsPerSecond: 64000 };
      const mediaRecorder = new MediaRecorder(stream, options);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        if (audioChunksRef.current.length === 0) return;
        const finalMimeType = mediaRecorder.mimeType || mimeType || 'audio/webm';
        const fileExt = finalMimeType.includes('mp4') ? 'mp4' : 'webm';
        const audioBlob = new Blob(audioChunksRef.current, { type: finalMimeType });

        setIsTranscribing(true);
        setIsUploading(true);

        // Upload
        const fileName = `voice-notes/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
        supabase.storage.from('journal-media').upload(fileName, audioBlob, { contentType: finalMimeType })
            .then(({ data, error }) => {
                if (!error && data) {
                    const { data: publicUrlData } = supabase.storage.from('journal-media').getPublicUrl(fileName);
                    setAudioUrl(publicUrlData.publicUrl);
                }
            })
            .finally(() => setIsUploading(false));

        // Transcribe (Optional for Drop, but good for context)
        if (mode !== 'drop') {
            const reader = new FileReader();
            reader.readAsDataURL(audioBlob);
            reader.onloadend = async () => {
                if (reader.result) {
                    const base64Audio = (reader.result as string).split(',')[1];
                    transcribeAudio(base64Audio, finalMimeType)
                        .then(text => setContent(prev => prev + (prev ? ' ' : '') + text))
                        .finally(() => setIsTranscribing(false));
                }
            };
        } else {
            setIsTranscribing(false);
        }
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) { console.error("Mic denied:", err); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const handleMicClick = () => isRecording ? stopRecording() : startRecording();

  const handleImageClick = () => {
      if (hasImage) { setHasImage(false); setImagePreview(null); } 
      else fileInputRef.current?.click();
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => { setImagePreview(reader.result as string); setHasImage(true); };
          reader.readAsDataURL(file);
      }
  };

  const handleFinalSubmit = () => {
       const type = mode === 'drop' ? EntryType.Drop : (hasImage ? EntryType.Photo : (audioUrl ? EntryType.Voice : EntryType.Prompt));
       // Drops are public by default to partner
       const isEntryPrivate = mode === 'drop' ? false : isPrivate; 

       onAddEntry(
           content, 
           selectedMood, 
           type, 
           dailyPrompt, 
           isEntryPrivate, 
           audioUrl || undefined, 
           imagePreview || undefined
       );
       setStep('success');
  };

  const isBusy = isTranscribing || isUploading;

  // --- DROP MODE RENDER ---
  if (mode === 'drop') {
      return (
          <div className="fixed inset-0 z-[200] bg-slate-950 text-white flex flex-col animate-fade-in w-screen h-screen overflow-hidden">
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

              {step === 'success' ? (
                  <div className="flex-1 flex flex-col items-center justify-center animate-scale-in relative z-20 p-6 text-center">
                      <div className="w-24 h-24 bg-white/10 rounded-full flex items-center justify-center animate-pulse-slow mb-8 backdrop-blur-md border border-white/20 shadow-glow">
                          <CheckCircle2 size={48} className="text-emerald-400" />
                      </div>
                      <h2 className="text-4xl md:text-5xl font-serif font-bold text-white mb-6 drop-shadow-lg">Dropped!</h2>
                      <p className="text-white/60 text-lg font-medium tracking-wide max-w-xs leading-relaxed mb-12">
                          {partnerName} will see this in your shared highlights.
                      </p>
                      {onClose && (
                          <button 
                            onClick={onClose} 
                            className="px-12 py-4 bg-white text-slate-950 rounded-full font-bold text-lg hover:scale-105 active:scale-95 transition-all shadow-xl"
                          >
                              Close
                          </button>
                      )}

                      {/* Success Background */}
                      <div className="absolute inset-0 z-[-1]">
                          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-emerald-500/20 rounded-full blur-[120px] animate-pulse-slow"></div>
                      </div>
                  </div>
              ) : (
                  <>
                      {/* Full Screen Background Layer */}
                      <div className="absolute inset-0 z-0 bg-slate-950">
                          {imagePreview ? (
                              <>
                                <img src={imagePreview} alt="Drop" className="w-full h-full object-cover" />
                                <div className="absolute inset-0 bg-black/30 backdrop-blur-[2px]"></div>
                                <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-black/50"></div>
                              </>
                          ) : (
                              <div className="w-full h-full bg-slate-950 flex flex-col items-center justify-center relative overflow-hidden">
                                  <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-500/20 rounded-full blur-[120px] animate-pulse-slow"></div>
                                  <div className="absolute top-0 right-0 w-[400px] h-[400px] bg-rose-500/10 rounded-full blur-[100px]"></div>
                              </div>
                          )}
                      </div>

                      {/* Top Bar */}
                      <div className="relative z-20 flex justify-between items-center p-6 pt-safe-top md:p-8 w-full">
                          <button 
                            onClick={onClose} 
                            className="w-12 h-12 flex items-center justify-center rounded-full bg-white/10 backdrop-blur-md text-white hover:bg-white/20 transition-all shadow-lg border border-white/5"
                          >
                              <X size={24} />
                          </button>
                          <div className="px-4 py-1.5 bg-black/20 backdrop-blur-md rounded-full border border-white/10">
                              <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-white/90">New Drop</span>
                          </div>
                          <div className="w-12"></div> {/* Spacer */}
                      </div>

                      {/* Main Content Area - Centered perfectly */}
                      <div className="relative z-10 flex-1 flex flex-col items-center justify-center p-6 w-full max-w-4xl mx-auto space-y-10">

                          {/* Text Input */}
                          <div className="w-full relative group">
                              <textarea
                                  value={content}
                                  onChange={handleContentChange}
                                  placeholder="3 words..."
                                  className="w-full bg-transparent text-center text-6xl md:text-8xl font-serif font-bold text-white placeholder:text-white/20 focus:outline-none resize-none drop-shadow-2xl leading-tight"
                                  rows={1}
                                  maxLength={40}
                                  autoFocus
                                  style={{ textShadow: '0 4px 20px rgba(0,0,0,0.5)' }}
                              />
                              <div className={`text-center mt-6 transition-all duration-500 ${content ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                                  <span className="text-[10px] font-bold uppercase tracking-widest text-white/80 bg-black/30 px-4 py-1.5 rounded-full backdrop-blur-md border border-white/10">
                                      {content.trim().split(/\s+/).filter(Boolean).length}/3 Words
                                  </span>
                              </div>
                          </div>

                          {/* Camera Trigger */}
                          {!imagePreview && (
                              <button 
                                onClick={handleImageClick}
                                className="flex flex-col items-center gap-4 group transition-transform active:scale-95 animate-float"
                              >
                                  <div className="w-24 h-24 rounded-[2.5rem] bg-white/5 border-2 border-dashed border-white/30 flex items-center justify-center group-hover:border-white group-hover:bg-white/10 transition-all shadow-2xl backdrop-blur-sm">
                                      <Camera size={40} className="text-white/60 group-hover:text-white transition-colors" />
                                  </div>
                                  <span className="text-xs font-bold uppercase tracking-widest text-white/50 group-hover:text-white transition-colors">Tap to Capture</span>
                              </button>
                          )}

                          {/* Audio Waveform */}
                          {audioUrl && (
                              <div className="flex items-center gap-4 bg-black/40 backdrop-blur-xl px-6 py-4 rounded-2xl border border-white/10 animate-slide-up shadow-xl">
                                  <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center shadow-lg">
                                      <Music size={18} className="text-white" />
                                  </div>
                                  <div className="flex gap-1 h-8 items-center">
                                      {[...Array(12)].map((_,i) => (
                                          <div key={i} className="w-1.5 bg-white/90 rounded-full animate-pulse" style={{height: `${Math.random() * 20 + 8}px`, animationDelay: `${i*0.05}s`}}></div>
                                      ))}
                                  </div>
                                  <button onClick={() => setAudioUrl(null)} className="ml-2 w-8 h-8 flex items-center justify-center rounded-full hover:bg-white/20 text-white/50 hover:text-white transition-colors"><X size={16}/></button>
                              </div>
                          )}
                      </div>

                      {/* Bottom Controls */}
                      <div className="relative z-20 w-full p-6 pb-12 md:pb-16">
                          <div className="max-w-3xl mx-auto flex items-center justify-between gap-4">
                              <button 
                                onClick={handleMicClick} 
                                className={`w-16 h-16 rounded-full flex items-center justify-center transition-all shadow-xl ${isRecording ? 'bg-red-500 scale-110 ring-4 ring-red-500/30' : 'bg-white/10 backdrop-blur-xl border border-white/10 hover:bg-white/20'}`}
                              >
                                  {isRecording ? <div className="w-6 h-6 bg-white rounded-sm animate-pulse" /> : <Mic size={24} className="text-white" />}
                              </button>

                              {imagePreview && (
                                  <button 
                                    onClick={handleImageClick} 
                                    className="hidden md:flex items-center gap-2 px-6 py-3 rounded-full bg-black/40 backdrop-blur-md text-white/70 hover:text-white hover:bg-black/60 transition-all text-xs font-bold uppercase tracking-widest border border-white/5"
                                  >
                                      <RefreshCw size={14} /> <span>Retake</span>
                                  </button>
                              )}

                              <button 
                                onClick={handleNext}
                                disabled={!hasImage || !content.trim() || isBusy} 
                                className={`h-16 px-10 md:px-16 rounded-full font-bold text-lg flex items-center gap-3 transition-all shadow-2xl ${(!hasImage || !content.trim() || isBusy) ? 'bg-white/10 text-white/30 cursor-not-allowed backdrop-blur-sm' : 'bg-white text-slate-900 hover:scale-105 active:scale-95 shadow-white/20'}`}
                              >
                                  <span>Drop It</span> <Send size={20} className={(!hasImage || !content.trim()) ? '' : 'fill-slate-900'} />
                              </button>
                          </div>

                          {imagePreview && (
                              <div className="md:hidden flex justify-center mt-6">
                                  <button onClick={handleImageClick} className="text-[10px] font-bold uppercase tracking-widest text-white/50 hover:text-white flex items-center gap-2 bg-black/20 px-4 py-2 rounded-full backdrop-blur-sm">
                                      <RefreshCw size={12} /> Retake Photo
                                  </button>
                              </div>
                          )}
                      </div>
                  </>
              )}
          </div>
      );
  }

  // --- STANDARD MODE RENDER (Existing) ---
  return (
    <div className="pb-32 pt-16 px-6 max-w-xl mx-auto h-full flex flex-col relative overflow-hidden">
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />
      <div className="fixed top-[-20%] right-[-10%] w-[600px] h-[600px] bg-belluh-300/10 rounded-full blur-[100px] pointer-events-none"></div>

      {step === 'success' ? (
        <div className="flex-1 flex flex-col items-center justify-center animate-scale-in">
           <div className="relative mb-8">
              <div className="w-24 h-24 bg-belluh-50 rounded-full flex items-center justify-center animate-pulse-slow">
                 <CheckCircle2 size={40} className="text-belluh-400" />
              </div>
           </div>
           <h2 className="text-3xl font-serif text-slate-900 mb-3 text-center">Moment Captured</h2>
           <p className="text-slate-500 text-sm font-medium tracking-wide text-center max-w-xs leading-relaxed">
               {!isPrivate ? `Belluh will remind ${partnerName} tonight.` : "Saved to your private vault."}
           </p>
        </div>
      ) : (
        <div className="relative flex-1 flex flex-col">
            <div className={`transition-all duration-500 flex-1 flex flex-col ${step === 'write' ? 'opacity-100 scale-100 z-10' : 'opacity-0 scale-95 pointer-events-none absolute inset-0'}`}>
                <div className="mb-8 mt-4">
                    <p className="text-xs font-bold text-belluh-400 uppercase tracking-widest mb-3">Daily Ritual</p>
                    <p className="text-2xl text-slate-800 font-serif leading-tight">{dailyPrompt}</p>
                </div>
                <div className="space-y-4 mb-4">
                    {hasImage && imagePreview && (
                        <div className="relative w-full h-48 rounded-2xl overflow-hidden shadow-sm animate-scale-in group">
                            <img src={imagePreview} alt="Attached" className="w-full h-full object-cover" />
                            <button onClick={handleImageClick} className="absolute top-2 right-2 bg-black/50 text-white p-1.5 rounded-full backdrop-blur-md">
                                <X size={14} />
                            </button>
                        </div>
                    )}
                    {(audioUrl || isUploading) && !isRecording && (
                        <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl border border-slate-100 animate-slide-up">
                            <div className="w-10 h-10 bg-slate-900 rounded-full flex items-center justify-center text-white">
                                {isUploading ? <Loader2 size={16} className="animate-spin" /> : <Mic size={16} />}
                            </div>
                            <div className="flex-1 text-xs font-bold">
                                {isUploading ? "Syncing Audio..." : "Voice Note Ready"}
                            </div>
                        </div>
                    )}
                </div>
                <textarea
                    value={content}
                    onChange={(e) => setContent(e.target.value)}
                    placeholder={isTranscribing ? "Transcribing your thoughts..." : "Start typing..."}
                    className="w-full bg-transparent text-slate-800 placeholder:text-slate-300 focus:outline-none resize-none font-serif text-xl leading-relaxed flex-1 transition-opacity duration-300"
                    style={{ opacity: isTranscribing ? 0.5 : 1 }}
                    autoFocus
                    disabled={isTranscribing}
                />
                <div className="mt-auto pt-6 flex items-center justify-between">
                    <div className="flex gap-2">
                         <button onClick={handleMicClick} disabled={isBusy} className={`h-12 px-5 rounded-full flex items-center gap-2 transition-all ${isRecording ? 'bg-red-50 text-red-500' : 'bg-slate-50 text-slate-500'}`}>
                            {isRecording ? <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" /> : (isTranscribing ? <Loader2 size={18} className="animate-spin" /> : <Mic size={18} />)}
                        </button>
                        {!isRecording && !isBusy && <button onClick={handleImageClick} className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${hasImage ? 'bg-belluh-50 text-belluh-600' : 'bg-slate-50 text-slate-500'}`}><ImageIcon size={18} /></button>}
                    </div>
                    {(content.trim() || hasImage || audioUrl) && !isRecording && !isBusy && (
                        <button onClick={handleNext} className="h-12 px-8 bg-slate-900 text-white rounded-full font-bold text-sm flex items-center gap-2">
                            <span>Next</span> <Send size={14} />
                        </button>
                    )}
                </div>
            </div>
            <div className={`transition-all duration-500 flex flex-col h-full ${step === 'mood' ? 'opacity-100 scale-100 z-10' : 'opacity-0 translate-x-10 pointer-events-none absolute inset-0'}`}>
                 <div className="flex justify-between items-center mb-10">
                    <h3 className="text-slate-800 font-serif text-2xl">How did this feel?</h3>
                    <button onClick={() => setStep('write')} className="text-xs font-bold text-slate-400 uppercase tracking-widest">Back</button>
                 </div>
                 <div className="grid grid-cols-4 gap-4 mb-auto">
                    {Object.values(Mood).map((m) => (
                        <button key={m} onClick={() => setSelectedMood(m)} className={`aspect-square rounded-2xl flex flex-col items-center justify-center transition-all ${selectedMood === m ? 'bg-white shadow-apple ring-2 ring-belluh-300' : 'bg-slate-50/50'}`}>
                        <span className="text-3xl">{MOOD_EMOJIS[m]}</span>
                        </button>
                    ))}
                 </div>
                 <div className="space-y-4 mb-8">
                     <div className="bg-slate-50 p-1.5 rounded-xl flex">
                         <button onClick={() => setIsPrivate(false)} className={`flex-1 py-3 rounded-lg text-xs font-bold uppercase transition-all ${!isPrivate ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}><Globe size={14} className="inline mr-2" />Share</button>
                         <button onClick={() => setIsPrivate(true)} className={`flex-1 py-3 rounded-lg text-xs font-bold uppercase transition-all ${isPrivate ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}><Lock size={14} className="inline mr-2" />Private</button>
                     </div>
                 </div>
                 <button onClick={handleFinalSubmit} disabled={!selectedMood} className={`w-full py-4 rounded-full font-bold text-sm shadow-xl flex items-center justify-center gap-2 ${selectedMood ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-300'}`}>
                    <span>Save to Story</span> <Send size={16} />
                 </button>
            </div>
        </div>
      )}
    </div>
  );
};

export default Journal;
